from pathlib import Path
import json
R=Path(__file__).resolve().parent
rows=[json.loads(s) for s in (R/'CLAIMS.jsonl').read_text(encoding='utf8').splitlines()]
for row in rows:
 row['checks']=row['checks'].replace('integer_gap in FiniteBellman.lean pending final compiler result.','integer_gap in FiniteBellman.lean accepted by Lean 4, exit 0, no warnings.').replace('finite Lean evaluation pending final compiler result.','finite Lean evaluation accepted with decide +kernel, exit 0, no warnings.')
rows.append({'problem_id':'C0020','claim':'For a nonconstant increasing Boolean function on fair bits, C(f)=I(f)^2/[4p(1-p)]+inf_A E[Var(M_A given f)], with M_A the sum of queried +/-1 bits over exact nonrepeating algorithms.','status':'proved','proof_location':'ATTEMPT.md Section 2, equations (3)-(4)','remaining_gap':'The infimum of conditional score variance is not bounded at a new percolation exponent; this is an equivalent reduction only.','checks':'Finite martingale identity, conditional means and law of total variance proved in full; 3x3 exact residual arithmetic gives 9039/16384.'})
(R/'CLAIMS.jsonl').write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in rows),encoding='utf8')
(R/'STATUS.md').write_text('STATE: DONE\nNEXT: Derive a percolation-specific estimate on the minimum conditional queried-score variance in ATTEMPT.md equation (4); no further work scheduled in this attempt.\nVERDICT: PARTIAL\n\n2026-10-12: Source fetched and model corrected: expected zero-error single-bit query cost for critical triangular-site square crossings; printed p.90/PDF p.92.\n2026-10-12: Queried arXiv, OpenAlex (source resolved; citing-works endpoint rate-limited), Crossref, Semantic Scholar (source and 118 citation records retrieved; keyword search rate-limited), and GitHub. No exact solution identified. The closely relevant 2024 paper explicitly calls the exponent open. This bounded search is not a proof of current openness.\n2026-10-12: Proved an integer-valued refinement of the influence-square bound and an exact conditional-score-variance reduction; the correction is bounded and does not improve the exponent.\n2026-10-12: Proved the 2x2 triangular rhombus optimum 5/2 by matching lower bound and explicit tree. Exact Bellman optima include 3x3 = 555/128 and 4x3 = 10685/2048. These are rhombus special cases, not the source square asymptotic problem.\n2026-10-12: All 197 monotone truth tables on <=4 bits passed exact inequality checks. Finite Bellman steps and integer gap accepted by Lean 4 with kernel checking, exit 0 and no warnings; no sorry. Largest computational run used about 130 MiB.\n2026-10-12: Attempt closed with the original exponent gap [3/2,7/4] unchanged. Full proofs, literature limitations, and remaining gap saved.\n',encoding='utf8')
assert (R/'STATUS.md').read_text().splitlines()[0]=='STATE: DONE'
assert (R/'lean_check.log').read_text().strip()=='exit_code=0'
assert len(rows)==6
assert not any(t in (R/'FiniteBellman.lean').read_text() for t in ['sorry','native_decide'])
print('Final artifacts checked:',len(rows),'claims; STATE DONE; VERDICT PARTIAL; Lean exit 0')
